from typing import Dict, List

from taf.gnb.oam.coam.vdu.exceptions import WrongApiResponseStatus, TimeoutException
from taf.internal.gnb.oam.coam.vdu.client.cp_config_licensed.v1.exceptions import ApiException

from taf.rfrl.procedures.resources.python.bts.components.rmod.cloud_rmod import CloudRmod
from taf.rfrl.procedures.resources.python.bts.utils.bts_types import Api
from taf.rfrl.procedures.resources.python.bts.utils.pretty_logger import pretty_log, log_info, log_debug
from taf.rfrl.procedures.resources.python.bts.utils.exceptions import AntennaLineOnlineMonitoringUnexpectedResult
from taf.rfrl.procedures.resources.python.bts.webem.webem_du import WebemDu


class AntennaLineOnlineMonitoring:
    """ Handles Antenna Line Online Monitoring functionality on BTS. """

    def __init__(self, webem: WebemDu, api: Api, api_alias: str):
        """
        :param webem: DU WebEM interface used for handling Antenna Line Online Monitoring on BTS
        :param api: API used for handling Antenna Line Online Monitoring on BTS
        :param api_alias: name of opened API connection which Antenna Line Online Monitoring should use
        """
        self._webem = webem
        self._api = api
        self._api_alias = api_alias

    @pretty_log
    def start_antenna_online_monitoring(self, antenna_lines: List[Dict], timeout: int = 30) -> int:
        """
        Starts the Antenna Line Online Monitoring procedure on the BTS and returns monitoring ID.
        :param antenna_lines: list of antenna lines to be monitored, e.g.:
                              [{"radioRId": 1, "antlRId": 1},
                               {"radioRId": 1, "antlRId": 2},
                               {"radioRId": 1, "phyAntlRId": 3},
                               {"radioRId": 1, "phyAntlRId": 4}]
        :param timeout: time (in seconds) in which Antenna Line Online Monitoring procedure should be successfully
                        started; defaults to 30
        :raises AntennaLineOnlineMonitoringUnexpectedResult: if starting Antenna Line Online Monitoring procedure fails
        :return: ID of the started Antenna Line Online Monitoring procedure, e.g. 1
        """
        log_info(f'Running Antenna Line Online Monitoring procedure with given antenna lines: {antenna_lines}',
                 to_console=True)
        result_msg = 'Result of starting Antenna Line Online Monitoring procedure is: {}'

        try:
            response = self._api.start_antenna_monitoring(antennas=antenna_lines,
                                                          timeout=timeout,
                                                          vdu_connection=self._api_alias,
                                                          wait_for_completion=True)
            monitoring_id = response['monitorId']
        except (ApiException,
                WrongApiResponseStatus,
                TimeoutException) as api_error:
            raise AntennaLineOnlineMonitoringUnexpectedResult(result_msg.format(api_error))

        log_debug(result_msg.format('success'))
        log_debug(f'Antenna Line Online Monitoring procedure ID: {monitoring_id}')

        return monitoring_id

    @pretty_log
    def start_antenna_online_monitoring_via_webem(self, rmods: List[CloudRmod], timeout: int = 60):
        """
        Starts the Antenna Line Online Monitoring procedure for antenna lines from RMODs via WebEM on the BTS.
        :param rmods: list of RMODs for which antenna lines will be monitored
        :param timeout: time (in seconds) within the element should be available to be clicked; defaults to 60
        :raises AntennaLineOnlineMonitoringUnexpectedResult: if starting Antenna Line Online Monitoring procedure fails
        """
        log_info(f'Running Antenna Line Online Monitoring procedure via WebEM for all antenna lines '
                 f'from RMODs: {[rmod.name for rmod in rmods]}', to_console=True)
        result_msg = 'Result of starting Antenna Line Online Monitoring procedure via WebEM is: {}'

        try:
            self._webem.start_antenna_monitoring(rmods=rmods,
                                                 timeout=timeout)
        except Exception as webem_error:
            raise AntennaLineOnlineMonitoringUnexpectedResult(result_msg.format(
                f'fail; exception raised: {type(webem_error).__name__}: {webem_error}'))

        log_debug(result_msg.format('success'))

    @pretty_log
    def stop_antenna_online_monitoring(self, monitoring_id: int, timeout: int = 30):
        """
        Stops the Antenna Line Online Monitoring procedure on the BTS.
        :param monitoring_id: ID of the Antenna Line Online Monitoring procedure to be stopped
        :param timeout: time (in seconds) in which Antenna Line Online Monitoring procedure should be successfully
                        stopped; defaults to 30
        :raises AntennaLineOnlineMonitoringUnexpectedResult: if stopping Antenna Line Online Monitoring procedure fails
        """
        log_info(f'Stopping Antenna Line Online Monitoring procedure with ID: {monitoring_id}', to_console=True)
        result_msg = 'Result of stopping Antenna Line Online Monitoring procedure is: {}'

        try:
            self._api.stop_antenna_monitoring(monitor_id=monitoring_id,
                                              timeout=timeout,
                                              vdu_connection=self._api_alias)
        except (ApiException,
                WrongApiResponseStatus,
                TimeoutException) as api_error:
            raise AntennaLineOnlineMonitoringUnexpectedResult(result_msg.format(api_error))

        log_debug(result_msg.format('success'))

    @pretty_log
    def stop_antenna_monitoring_via_webem(self, timeout: int = 60):
        """
        Stops the Antenna Line Online Monitoring procedure via WebEM on the BTS.
        :param timeout: time (in seconds) within the element should be available to be clicked; defaults to 60
        :raises AntennaLineOnlineMonitoringUnexpectedResult: if stopping Antenna Line Online Monitoring procedure fails
        """
        log_info('Stopping Antenna Line Online Monitoring procedure via WebEM', to_console=True)
        result_msg = 'Result of stopping Antenna Line Online Monitoring procedure via WebEM is: {}'

        try:
            self._webem.stop_antenna_monitoring(timeout=timeout)
        except Exception as webem_error:
            raise AntennaLineOnlineMonitoringUnexpectedResult(result_msg.format(
                f'fail; exception raised: {type(webem_error).__name__}: {webem_error}'))

        log_debug(result_msg.format('success'))

    @pretty_log
    def get_antenna_online_monitoring_results(self, monitoring_id: int, timeout: int = 30) -> List[Dict]:
        """
        Gets the results of the Antenna Line Online Monitoring procedure.
        :param monitoring_id: ID of the Antenna Line Online Monitoring procedure for which results are to be retrieved
        :param timeout: time (in seconds) in which Antenna Line Online Monitoring results should be successfully
                        retrieved; defaults to 30
        :raises AntennaLineOnlineMonitoringUnexpectedResult: if retrieving Antenna Line Online Monitoring results fails
        :return: list of results from the Antenna Line Online Monitoring procedure, e.g.:
                 [{'cell': {'name': 'NRCELL-5'},
                   'measurementType': 'ETP',
                   'measurements': [{'timestamp': '2025-07-02T12:11:22+00:00', 'value': '1995.3'},
                                    {'timestamp': '2025-07-02T12:11:32+00:00', 'value': '1995.3'}],
                   'productName': 'AVHA',
                   'rmodId': {'configId': 5, 'runtimeId': 5}},
                  {'cell': {'name': 'NRCELL-5'},
                   'measurementType': 'RTWP',
                   'measurements': [{'timestamp': '2025-07-02T12:11:22+00:00', 'value': '-86.6'},
                                    {'timestamp': '2025-07-02T12:11:32+00:00', 'value': '-86.6'}],
                   'productName': 'AVHA',
                   'rmodId': {'configId': 5, 'runtimeId': 5}}]
        """
        log_info(f'Getting Antenna Line Online Monitoring results for procedure with ID: {monitoring_id}',
                 to_console=True)
        result_msg = 'Result of getting Antenna Line Online Monitoring results is: {}'

        try:
            results = self._api.get_antenna_monitoring_results(monitor_id=monitoring_id,
                                                               timeout=timeout,
                                                               vdu_connection=self._api_alias)
        except (ApiException,
                WrongApiResponseStatus,
                TimeoutException) as api_error:
            error_msg = result_msg.format(api_error)
            raise AntennaLineOnlineMonitoringUnexpectedResult(error_msg)

        log_debug(result_msg.format('success'))
        log_debug(f'Retrieved Antenna Line Online Monitoring results: {results}')

        return results

    @pretty_log
    def get_antenna_online_monitoring_results_via_webem(self, timeout: int = 60) -> dict:
        """
        Gets the Antenna Line Online Monitoring results from WebEM tables.
        :param timeout: time (in seconds) within the element should be available to be clicked; defaults to 60
        :raises AntennaLineOnlineMonitoringUnexpectedResult: if retrieving Antenna Line Online Monitoring results via WebEM fails
        :return: Antenna Line Online Monitoring results as a dictionary, e.g.:
                 {'VSWR (Total 6 time interval(s))':
                    {'measurements': {'ANT1': {'Radio module': 'RMOD-2/RMOD_R-2(AZQU)',
                                               'Source': 'ANT1',
                                               'Supported TX bands': 'n77 (3900MHz - 4099.9MHz)',
                                               '23.01.2026 14:09:59 GMT+0000': '-',
                                               '23.01.2026 14:09:49 GMT+0000': '-',
                                               '23.01.2026 14:09:39 GMT+0000': '-'},
                                      'ANT2': {'Radio module': ...}}}}
        """
        log_info('Getting Antenna Line Online Monitoring results from WebEM tables',
                 to_console=True)
        result_msg = 'Result of getting Antenna Line Online Monitoring results from WebEM tables is: {}'

        try:
            results = self._webem.get_antenna_monitoring_results(timeout=timeout)
        except Exception as webem_error:
            raise AntennaLineOnlineMonitoringUnexpectedResult(result_msg.format(
                f'fail; exception raised: {type(webem_error).__name__}: {webem_error}'))

        log_debug(result_msg.format('success'))
        log_debug(f'Retrieved Antenna Line Online Monitoring results via WebEM: {results}')

        return results

    @pretty_log
    def get_antenna_online_monitoring_json_result_file(self, directory: str, timeout: int = 30) -> str:
        """
        Gets the Antenna Line Online Monitoring json results file and saves it to the specified directory.
        :param directory: directory where the Antenna Line Online Monitoring results file should be saved, e.g.:
                          '/path/to/directory'
        :param timeout: time (in seconds) in which Antenna Line Online Monitoring results file should be successfully
                        retrieved; defaults to 30
        :raises AntennaLineOnlineMonitoringUnexpectedResult: if retrieving Antenna Line Online Monitoring results file
                                                             fails
        :return: path to the saved Antenna Line Online Monitoring results file, e.g.:
                 '/path/to/directory/antenna_monitoring_results_2025-07-02T12-11-22.zip'
        """
        log_info(f'Saving Antenna Line Online Monitoring json results file package to directory: {directory}',
                 to_console=True)
        result_msg = 'Result of getting Antenna Line Online Monitoring json results file is: {}'

        try:
            results_filepath = self._api.get_antenna_monitoring_result_file(directory=directory,
                                                                            timeout=timeout,
                                                                            vdu_connection=self._api_alias)
        except (ApiException,
                WrongApiResponseStatus,
                TimeoutException) as api_error:
            raise AntennaLineOnlineMonitoringUnexpectedResult(result_msg.format(api_error))

        log_debug(result_msg.format('success'))
        log_debug(f'Antenna Line Online Monitoring json results file package saved to: {results_filepath}')

        return results_filepath

    @pretty_log
    def get_antenna_online_monitoring_csv_result_file_via_webem(self, timeout: int = 60) -> str:
        """
        Gets the Antenna Line Online Monitoring csv results file and saves it in test environment download directory.
        :param timeout: time (in seconds) within the element should be available to be clicked; defaults to 60
        :raises AntennaLineOnlineMonitoringUnexpectedResult: if retrieving Antenna Line Online Monitoring csv results
                                                             file fails
        :return: path to the saved Antenna Line Online Monitoring results file, e.g.:
                 '/path/to/dir/ANTLMonitoring_MRBTS-8463_vDU_8463_CB012220_vDUCNF25R3_26.300.380_20250917-0511.csv'
        """
        log_info('Saving Antenna Line Online Monitoring results csv file',
                 to_console=True)
        result_msg = 'Result of getting Antenna Line Online Monitoring results csv file is: {}'

        try:
            results_filepath = self._webem.export_antenna_monitoring_data_to_csv(timeout=timeout)
        except Exception as webem_error:
            raise AntennaLineOnlineMonitoringUnexpectedResult(result_msg.format(
                f'fail; exception raised: {type(webem_error).__name__}: {webem_error}'))

        log_debug(result_msg.format('success'))
        log_debug(f'Antenna Line Online Monitoring results csv file saved to: {results_filepath}')

        return results_filepath
